     1	<!DOCTYPE html>
     2	<html lang="zh-CN">
     3	<head>
     4	<meta charset="UTF-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0">
     6	<title>数字员工世界 · 打工小队上线</title>
     7	<link rel="preconnect" href="https://fonts.googleapis.com">
     8	<link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Noto+Sans+SC:wght@400;500;700;900&display=swap" rel="stylesheet">
     9	<style>
    10	  :root{
    11	    --sky-top:#CDEBFF;
    12	    --sky-mid:#E4E9FF;
    13	    --sky-bottom:#FBEAF7;
    14	    --ink:#1B2340;
    15	    --ink-soft:#5A6088;
    16	    --gold:#FFC24B;
    17	    --gold-dark:#E8A11E;
    18	
    19	    --blue:#3E8EDE;      --blue-d:#2A6BB0;      --blue-l:#DCEEFF;
    20	    --orange:#FF8A3D;    --orange-d:#DB6A22;    --orange-l:#FFE7D6;
    21	    --green:#39AE7C;     --green-d:#268A5D;     --green-l:#DAF3E7;
    22	    --purple:#9767D6;    --purple-d:#7548B0;    --purple-l:#EDE1FA;
    23	    --pink:#FF6FA0;      --pink-d:#DB4F82;      --pink-l:#FFE0EC;
    24	
    25	    --panel-dark:#171F36;
    26	    --panel-line:#2C3653;
    27	  }
    28	
    29	  *{box-sizing:border-box; margin:0; padding:0;}
    30	  html,body{height:100%;}
    31	  body{
    32	    font-family:"Noto Sans SC", sans-serif;
    33	    color:var(--ink);
    34	    background:linear-gradient(180deg, var(--sky-top) 0%, var(--sky-mid) 38%, var(--sky-bottom) 100%);
    35	    min-height:100svh;
    36	    padding-bottom:10vh;
    37	  }
    38	  .num{ font-family:"Fredoka","Noto Sans SC",sans-serif; }
    39	  button{ font-family:inherit; border:none; background:none; cursor:pointer; }
    40	  ::selection{ background:var(--gold); color:var(--ink); }
    41	
    42	  @media (prefers-reduced-motion: reduce){
    43	    *{ animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important; }
    44	  }
    45	
    46	  /* ---------- hero ---------- */
    47	  .hero{
    48	    position:relative;
    49	    padding:7vh 5vw 3vh;
    50	    display:flex; flex-direction:column; align-items:center; text-align:center;
    51	    overflow:hidden;
    52	  }
    53	  .cloud{ position:absolute; background:#fff; border-radius:100px; opacity:.85; }
    54	  .cloud::before,.cloud::after{ content:""; position:absolute; background:#fff; border-radius:100px; }
    55	  .cloud1{ width:110px; height:36px; top:6%; left:6%; animation:drift 40s linear infinite; }
    56	  .cloud1::before{ width:54px; height:54px; top:-24px; left:14px; }
    57	  .cloud1::after{ width:40px; height:40px; top:-16px; left:56px; }
    58	  .cloud2{ width:80px; height:28px; top:10%; right:8%; animation:drift 48s linear infinite reverse; }
    59	  .cloud2::before{ width:42px; height:42px; top:-20px; left:8px; }
    60	  .cloud2::after{ width:32px; height:32px; top:-12px; left:40px; }
    61	  @keyframes drift{ from{ transform:translateX(-40px);} to{ transform:translateX(calc(100vw + 40px));} }
    62	
    63	  .eyebrow{
    64	    font-family:"Fredoka",sans-serif; font-size:13px; letter-spacing:.28em;
    65	    color:var(--orange-d); background:#fff; padding:6px 16px; border-radius:999px;
    66	    box-shadow:0 3px 0 rgba(219,106,34,.18); position:relative; z-index:2;
    67	  }
    68	  h1.title{ margin-top:18px; font-size:clamp(28px,5vw,52px); font-weight:900; line-height:1.15; position:relative; z-index:2; }
    69	  h1.title .hl{ color:var(--orange); text-shadow:3px 3px 0 rgba(27,35,64,.12); }
    70	  .subtitle{ margin-top:12px; font-size:clamp(13px,1.8vw,16px); color:var(--ink-soft); max-width:520px; z-index:2; position:relative; }
    71	
    72	  /* ---------- category filter ---------- */
    73	  .filters{
    74	    display:flex; flex-wrap:wrap; justify-content:center; gap:10px;
    75	    margin-top:26px; z-index:2; position:relative;
    76	    max-width:760px;
    77	  }
    78	  .filter-pill{
    79	    font-size:13px; font-weight:700; color:var(--ink-soft);
    80	    background:#fff; padding:9px 18px; border-radius:999px;
    81	    border:1.5px solid transparent;
    82	    box-shadow:0 2px 6px rgba(27,35,64,.08);
    83	    display:flex; align-items:center; gap:7px;
    84	    transition:transform .15s ease, border-color .15s ease, color .15s ease;
    85	  }
    86	  .filter-pill .dot{ width:8px; height:8px; border-radius:50%; background:var(--dot,#ccc); }
    87	  .filter-pill:hover{ transform:translateY(-2px); }
    88	  .filter-pill.active{ color:var(--ink); border-color:var(--dot,var(--ink)); }
    89	
    90	  /* ---------- card grid ---------- */
    91	  .grid{
    92	    max-width:1320px;
    93	    margin:5vh auto 0;
    94	    padding:0 4vw;
    95	    display:grid;
    96	    grid-template-columns:repeat(auto-fill, minmax(210px, 1fr));
    97	    gap:20px;
    98	  }
    99	  .card-3d{
   100	    width:100%; height:340px;
   101	    perspective:1100px;
   102	    opacity:0; transform:translateY(20px) scale(.98);
   103	    animation:riseIn .55s cubic-bezier(.2,.8,.2,1) forwards;
   104	    transition:opacity .25s ease, transform .25s ease;
   105	  }
   106	  .card-3d.hidden{ display:none; }
   107	  .card-3d:nth-child(5n+1){ animation-delay:.03s; }
   108	  .card-3d:nth-child(5n+2){ animation-delay:.1s; }
   109	  .card-3d:nth-child(5n+3){ animation-delay:.17s; }
   110	  .card-3d:nth-child(5n+4){ animation-delay:.24s; }
   111	  .card-3d:nth-child(5n+5){ animation-delay:.31s; }
   112	  @keyframes riseIn{ to{ opacity:1; transform:translateY(0) scale(1);} }
   113	
   114	  .card-inner{
   115	    position:relative; width:100%; height:100%;
   116	    border-radius:22px;
   117	    background:linear-gradient(160deg, var(--c-light) 0%, #fff 62%);
   118	    border:1px solid rgba(0,0,0,.04);
   119	    box-shadow:0 18px 34px -14px rgba(27,35,64,.28), 0 2px 0 rgba(255,255,255,.6) inset;
   120	    padding:20px 20px 18px;
   121	    display:flex; flex-direction:column; justify-content:space-between;
   122	    cursor:pointer;
   123	    transform-style:preserve-3d;
   124	    transition:transform .16s ease-out, box-shadow .16s ease-out;
   125	  }
   126	  .card-inner:hover{ box-shadow:0 24px 42px -16px rgba(27,35,64,.34), 0 2px 0 rgba(255,255,255,.6) inset; }
   127	
   128	  /* ---------- 数字员工大盘 banner ---------- */
   129	  .dash-banner{
   130	    max-width:1080px; margin:5vh auto 0; padding:0 5vw;
   131	  }
   132	  .dash-banner a{
   133	    display:flex; align-items:center; gap:22px; flex-wrap:wrap;
   134	    background:linear-gradient(160deg, var(--panel-dark, #171F36) 0%, #0F1424 120%);
   135	    border:1px solid rgba(255,255,255,.08);
   136	    border-radius:20px; padding:22px 26px;
   137	    box-shadow:0 18px 40px -18px rgba(15,20,36,.55);
   138	    transition:transform .18s ease, box-shadow .18s ease;
   139	  }
   140	  .dash-banner a:hover{ transform:translateY(-3px); box-shadow:0 24px 48px -18px rgba(15,20,36,.65); }
   141	  .dash-banner .db-icon{
   142	    width:46px; height:46px; border-radius:14px; flex:0 0 auto;
   143	    background:linear-gradient(160deg, var(--blue), var(--purple));
   144	    display:flex; align-items:center; justify-content:center; font-size:20px;
   145	  }
   146	  .dash-banner .db-body{ flex:1; min-width:180px; }
   147	  .dash-banner .db-title{ color:#fff; font-size:15.5px; font-weight:900; display:flex; align-items:center; gap:8px; }
   148	  .dash-banner .db-live{ display:inline-flex; align-items:center; gap:5px; font-size:10px; font-weight:700; color:var(--green); background:rgba(57,174,124,.15); padding:2px 8px; border-radius:999px; }
   149	  .dash-banner .db-live i{ width:5px; height:5px; border-radius:50%; background:var(--green); box-shadow:0 0 0 2px rgba(57,174,124,.3); }
   150	  .dash-banner .db-sub{ color:rgba(255,255,255,.5); font-size:12px; margin-top:4px; }
   151	  .dash-banner .db-stats{ display:flex; gap:22px; flex-wrap:wrap; }
   152	  .dash-banner .db-stat{ text-align:center; }
   153	  .dash-banner .db-stat .v{ font-family:"Fredoka",sans-serif; font-size:17px; font-weight:700; color:#fff; }
   154	  .dash-banner .db-stat .k{ font-size:10px; color:rgba(255,255,255,.4); margin-top:2px; }
   155	  .dash-banner .db-cta{
   156	    flex:0 0 auto; font-size:12.5px; font-weight:700; color:#10162A;
   157	    background:#fff; padding:11px 20px; border-radius:999px;
   158	    display:inline-flex; align-items:center; gap:6px;
   159	  }
   160	  @media (max-width:640px){ .dash-banner .db-stats{ display:none; } }
   161	
   162	  .card-topline{ display:flex; align-items:center; justify-content:space-between; gap:8px; }
   163	  .card-cat{
   164	    font-size:10.5px; font-weight:700; color:var(--c-dark);
   165	    background:var(--c-light); padding:4px 10px; border-radius:999px;
   166	    white-space:nowrap;
   167	  }
   168	  .card-role{ font-size:10.5px; color:var(--ink-soft); }
   169	
   170	  .stage3d{ flex:1; display:flex; align-items:center; justify-content:center; perspective:600px; }
   171	  .pal{ position:relative; width:96px; height:120px; transition:transform .16s ease-out; }
   172	  .pal .shadow{ position:absolute; width:54px; height:15px; left:50%; bottom:2px; margin-left:-27px; background:rgba(20,25,50,.18); border-radius:50%; filter:blur(3px); }
   173	  .pal .body{ position:absolute; width:62px; height:78px; left:50%; margin-left:-31px; top:12px; background:var(--c-main); border-radius:44% 44% 50% 50% / 48% 48% 52% 52%; box-shadow:inset -9px -11px 0 rgba(0,0,0,.12), inset 7px 9px 0 rgba(255,255,255,.28); }
   174	  .pal .goggle{ position:absolute; width:40px; height:26px; left:50%; margin-left:-20px; top:28px; background:#fff; border:3px solid var(--ink); border-radius:14px; display:flex; align-items:center; justify-content:center; }
   175	  .pal .goggle svg{ width:19px; height:19px; }
   176	  .pal .arm{ position:absolute; width:9px; height:24px; border-radius:6px; top:40px; background:var(--c-main); }
   177	  .pal .arm.l{ left:50%; margin-left:-38px; transform-origin:top center; animation:swayL 2.6s ease-in-out infinite; }
   178	  .pal .arm.r{ left:50%; margin-left:29px; transform-origin:top center; animation:swayR 2.6s ease-in-out infinite; }
   179	  @keyframes swayL{ 0%,100%{ transform:rotate(6deg);} 50%{ transform:rotate(-4deg);} }
   180	  @keyframes swayR{ 0%,100%{ transform:rotate(-6deg);} 50%{ transform:rotate(4deg);} }
   181	  .pal-bob{ animation:bob 3s ease-in-out infinite; transform-style:preserve-3d; }
   182	  @keyframes bob{ 0%,100%{ transform:translateZ(0) translateY(0);} 50%{ transform:translateZ(26px) translateY(-6px);} }
   183	
   184	  .card-bottom .name{ font-size:20px; font-weight:900; color:var(--ink); }
   185	  .card-bottom .hook{ font-size:11.5px; color:var(--c-dark); margin-top:6px; line-height:1.5; min-height:2.7em; }
   186	  .card-bottom .cta-hint{ margin-top:10px; font-size:11px; font-weight:700; color:var(--c-dark); display:flex; align-items:center; gap:4px; }
   187	
   188	  .c-blue{ --c-main:var(--blue); --c-dark:var(--blue-d); --c-light:var(--blue-l); --dot:var(--blue); }
   189	  .c-orange{ --c-main:var(--orange); --c-dark:var(--orange-d); --c-light:var(--orange-l); --dot:var(--orange); }
   190	  .c-green{ --c-main:var(--green); --c-dark:var(--green-d); --c-light:var(--green-l); --dot:var(--green); }
   191	  .c-purple{ --c-main:var(--purple); --c-dark:var(--purple-d); --c-light:var(--purple-l); --dot:var(--purple); }
   192	  .c-pink{ --c-main:var(--pink); --c-dark:var(--pink-d); --c-light:var(--pink-l); --dot:var(--pink); }
   193	
   194	  @media (max-width:640px){
   195	    .grid{ gap:16px; grid-template-columns:repeat(auto-fill, minmax(240px,1fr)); }
   196	    .card-3d{ height:330px; }
   197	  }
   198	
   199	  /* ================= MODAL ================= */
   200	  .overlay{
   201	    position:fixed; inset:0; z-index:100;
   202	    background:rgba(10,14,28,.6);
   203	    backdrop-filter:blur(3px);
   204	    display:flex; align-items:flex-end; justify-content:center;
   205	    opacity:0; visibility:hidden;
   206	    transition:opacity .3s ease, visibility 0s linear .3s;
   207	  }
   208	  .overlay.open{ opacity:1; visibility:visible; transition:opacity .3s ease; }
   209	  @media (min-width:720px){ .overlay{ align-items:center; padding:4vh 0; } }
   210	
   211	  .modal{
   212	    position:relative;
   213	    width:100%; max-width:760px; max-height:94vh;
   214	    background:var(--panel-dark); color:#fff;
   215	    border-radius:24px 24px 0 0; overflow:hidden;
   216	    display:flex; flex-direction:column;
   217	    transform:translateY(28px);
   218	    transition:transform .35s cubic-bezier(.2,.8,.2,1);
   219	    box-shadow:0 -10px 50px rgba(0,0,0,.4);
   220	  }
   221	  @media (min-width:720px){ .modal{ border-radius:24px; max-height:88vh; } }
   222	  .overlay.open .modal{ transform:translateY(0); }
   223	
   224	  .modal-head{
   225	    position:relative; padding:22px 22px 18px; display:flex; align-items:center; gap:16px;
   226	    background:linear-gradient(160deg, var(--c-main) 0%, var(--panel-dark) 130%);
   227	    flex:0 0 auto;
   228	  }
   229	  .modal-close{ position:absolute; top:14px; right:14px; width:32px; height:32px; border-radius:50%; background:rgba(0,0,0,.25); color:#fff; font-size:16px; display:flex; align-items:center; justify-content:center; }
   230	  .modal-avatar{ position:relative; width:70px; height:88px; flex:0 0 auto; }
   231	  .modal-avatar .body{ position:absolute; width:60px; height:74px; left:5px; top:10px; background:var(--c-main); border-radius:44% 44% 50% 50%/48% 48% 52% 52%; box-shadow:inset -8px -10px 0 rgba(0,0,0,.15), inset 6px 8px 0 rgba(255,255,255,.25); }
   232	  .modal-avatar .goggle{ position:absolute; width:38px; height:24px; left:16px; top:26px; background:#fff; border:2.5px solid #10162A; border-radius:13px; display:flex; align-items:center; justify-content:center; }
   233	  .modal-avatar .goggle svg{ width:18px; height:18px; }
   234	  .modal-id{ flex:1; min-width:0; }
   235	  .modal-id .name{ font-size:22px; font-weight:900; }
   236	  .modal-id .role{ font-size:12.5px; color:rgba(255,255,255,.85); margin-top:2px; }
   237	  .modal-id .meta{ font-size:11px; color:rgba(255,255,255,.65); margin-top:6px; display:flex; gap:10px; flex-wrap:wrap; }
   238	  .modal-id .cat-chip{ font-size:10.5px; font-weight:700; background:rgba(255,255,255,.18); padding:3px 9px; border-radius:999px; margin-top:6px; display:inline-block; }
   239	  .status-dot{ display:inline-block; width:7px; height:7px; border-radius:50%; background:#4CD97B; margin-right:4px; box-shadow:0 0 0 3px rgba(76,217,123,.25); }
   240	
   241	  .health-ring{ flex:0 0 auto; width:64px; height:64px; position:relative; }
   242	  .health-ring svg{ width:100%; height:100%; transform:rotate(-90deg); }
   243	  .health-ring .track{ fill:none; stroke:rgba(255,255,255,.18); stroke-width:6; }
   244	  .health-ring .prog{ fill:none; stroke:#fff; stroke-width:6; stroke-linecap:round; transition:stroke-dashoffset 1s ease; }
   245	  .health-ring .val{ position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; }
   246	  .health-ring .val b{ font-family:"Fredoka",sans-serif; font-size:17px; }
   247	  .health-ring .val span{ font-size:8px; color:rgba(255,255,255,.7); }
   248	
   249	  .modal-body{ overflow-y:auto; padding:4px 22px 28px; }
   250	  .sec{ margin-top:22px; }
   251	  .sec-title{ font-size:12.5px; font-weight:700; letter-spacing:.04em; color:rgba(255,255,255,.55); display:flex; align-items:center; gap:8px; margin-bottom:10px; }
   252	  .sec-title::before{ content:""; width:3px; height:13px; border-radius:2px; background:var(--c-main); }
   253	
   254	  .scenario{ display:flex; align-items:flex-start; gap:10px; background:rgba(255,255,255,.04); border:1px solid var(--panel-line); border-radius:12px; padding:11px 13px; margin-bottom:8px; }
   255	  .scenario .flow{ font-size:12.5px; line-height:1.55; }
   256	  .scenario .flow .trig{ color:rgba(255,255,255,.6); }
   257	  .scenario .flow .act{ color:#fff; font-weight:700; }
   258	  .scenario .eff{ margin-top:5px; display:inline-block; font-size:11px; font-weight:700; color:var(--c-main); background:rgba(255,255,255,.06); padding:2px 9px; border-radius:999px; }
   259	
   260	  .skill-row{ margin-bottom:9px; }
   261	  .skill-row .top{ display:flex; justify-content:space-between; font-size:12px; margin-bottom:4px; }
   262	  .skill-row .top .sname{ color:#fff; font-weight:500; }
   263	  .skill-row .top .spct{ color:rgba(255,255,255,.55); font-family:"Fredoka",sans-serif; }
   264	  .skill-bar{ height:6px; border-radius:4px; background:rgba(255,255,255,.08); overflow:hidden; }
   265	  .skill-bar i{ display:block; height:100%; background:var(--c-main); border-radius:4px; }
   266	
   267	  .tagwrap{ display:flex; flex-wrap:wrap; gap:7px; }
   268	  .tagwrap span{ font-size:11.5px; color:rgba(255,255,255,.85); background:rgba(255,255,255,.06); border:1px solid var(--panel-line); padding:5px 11px; border-radius:999px; }
   269	  .bound-row{ display:flex; gap:8px; font-size:12px; margin-bottom:6px; color:rgba(255,255,255,.75); }
   270	  .bound-row b{ color:#fff; font-weight:700; min-width:64px; flex:0 0 auto; }
   271	
   272	  .effect-grid{ display:grid; grid-template-columns:repeat(2,1fr); gap:10px; }
   273	  @media (min-width:520px){ .effect-grid{ grid-template-columns:repeat(4,1fr); } }
   274	  .effect-card{ background:linear-gradient(160deg, rgba(255,255,255,.07), rgba(255,255,255,.02)); border:1px solid var(--panel-line); border-radius:14px; padding:13px 10px; text-align:center; }
   275	  .effect-card .v{ font-family:"Fredoka",sans-serif; font-size:17px; font-weight:700; color:var(--c-main); line-height:1.2; }
   276	  .effect-card .k{ font-size:10.5px; color:rgba(255,255,255,.6); margin-top:4px; }
   277	
   278	  .stat-grid{ display:grid; grid-template-columns:repeat(2,1fr); gap:8px; }
   279	  @media (min-width:520px){ .stat-grid{ grid-template-columns:repeat(4,1fr); } }
   280	  .stat-card{ background:#10162A; border:1px solid var(--panel-line); border-radius:11px; padding:10px; }
   281	  .stat-card .v{ font-family:"Fredoka",sans-serif; font-size:15px; font-weight:700; color:#fff; }
   282	  .stat-card .k{ font-size:10px; color:rgba(255,255,255,.5); margin-top:2px; }
   283	
   284	  .trend{ display:flex; align-items:flex-end; gap:4px; height:44px; margin-top:12px; }
   285	  .trend i{ flex:1; background:var(--c-main); opacity:.35; border-radius:3px 3px 0 0; }
   286	  .trend i:last-child{ opacity:1; }
   287	
   288	  .health-breakdown{ display:flex; gap:14px; margin-top:12px; flex-wrap:wrap; }
   289	  .hb-item{ flex:1; min-width:120px; }
   290	  .hb-item .top{ display:flex; justify-content:space-between; font-size:11px; color:rgba(255,255,255,.6); margin-bottom:4px; }
   291	  .hb-bar{ height:5px; border-radius:3px; background:rgba(255,255,255,.08); overflow:hidden; }
   292	  .hb-bar i{ display:block; height:100%; border-radius:3px; }
   293	
   294	  .cta-final{ margin-top:24px; width:100%; background:var(--c-main); color:#10162A; font-weight:700; font-size:14px; padding:14px 0; border-radius:999px; text-align:center; transition:filter .15s ease, transform .15s ease; }
   295	  .cta-final:hover{ filter:brightness(1.08); transform:translateY(-2px); }
   296	
   297	  .toast{
   298	    position:fixed; left:50%; bottom:24px; transform:translate(-50%,20px);
   299	    background:#10162A; color:#fff; border:1px solid rgba(255,255,255,.12);
   300	    padding:12px 20px; border-radius:999px; font-size:13px;
   301	    opacity:0; transition:opacity .25s ease, transform .25s ease;
   302	    z-index:120; pointer-events:none;
